document.addEventListener('click',event=>{
  const page=event.target.closest('[data-simple-page]');if(page){event.preventDefault();event.stopImmediatePropagation();db.simplePage=page.dataset.simplePage;db.legacyPage='';commit();return}
  const legacy=event.target.closest('[data-open-legacy]');if(legacy){event.preventDefault();event.stopImmediatePropagation();db.legacyPage=legacy.dataset.openLegacy;commit();return}
  if(event.target.closest('[data-close-legacy]')){db.legacyPage='';commit();return}
  const mode=event.target.closest('[data-start-mode]');if(mode){db.simplePage='contribuicoes';trip().contributionPlan={...(trip().contributionPlan||{}),mode:mode.dataset.startMode};commit();return}
  const payment=event.target.closest('[data-simple-payment]');if(payment){const [personId,month]=payment.dataset.simplePayment.split('|');simplePaymentModal(personId,month);return}
  const confirmMonth=event.target.closest('[data-confirm-month]');if(confirmMonth){const [personId,month]=confirmMonth.dataset.confirmMonth.split('|');saveQuickMonthly(personId,month);return}
  if(event.target.closest('[data-add-simple-expense]')){simpleExpenseModal();return}
  const payExpense=event.target.closest('[data-pay-expense]');if(payExpense){simpleExpensePaymentModal(payExpense.dataset.payExpense);return}
  const report=event.target.closest('[data-person-report]');if(report){personReportModal(report.dataset.personReport);return}
  const imageReport=event.target.closest('[data-report-image-action]');if(imageReport){handlePersonReportImage(imageReport.dataset.reportPerson,imageReport.dataset.reportImageAction);return}
  if(event.target.closest('[data-group-payment]')){groupPaymentModal();return}
  const editGroup=event.target.closest('[data-edit-group-payment]');if(editGroup){groupPaymentModal(db.payments.find(payment=>payment.id===editGroup.dataset.editGroupPayment));return}
  const surplus=event.target.closest('[data-surplus]');if(surplus){trip().surplusPolicy=surplus.dataset.surplus;commit('Destino da sobra atualizado.');return}
  const year=event.target.closest('[data-shopping-year]');if(year){db.shoppingYear=Number(year.dataset.shoppingYear);render();return}
  const leftover=event.target.closest('[data-shopping-leftover]');if(leftover){const item=db.shoppingItems.find(value=>value.id===leftover.dataset.shoppingLeftover);item.leftover=!item.leftover;commit();return}
  if(event.target.closest('[data-copy-shopping]')){const source=Number(db.shoppingYear)||shoppingYears()[0]||new Date().getFullYear(),target=source+1;if(tripShopping().some(item=>item.year===target))return toast(`A lista de ${target} já existe.`,'error');tripShopping().filter(item=>item.year===source).forEach(item=>db.shoppingItems.push({...item,id:uid(),year:target,actualTotalCents:null,leftover:false}));db.shoppingYear=target;commit(`Lista copiada para ${target}.`);return}
  const mapCard=event.target.closest('[data-map-member]');if(mapCard&&!simpleMapMoved&&!event.target.closest('button,input')){event.preventDefault();const memberId=mapCard.dataset.mapMember;mapSelection.has(memberId)?mapSelection.delete(memberId):mapSelection.add(memberId);render();if(mapSelection.size===2)toast('Duas pessoas selecionadas. Use “Conectar manualmente”.');return}
},true);

document.addEventListener('pointerdown',event=>{const card=event.target.closest?.('[data-map-member]');if(card&&!event.target.closest('button,input')){simpleMapPointer={x:event.clientX,y:event.clientY};simpleMapMoved=false}},true);
document.addEventListener('pointermove',event=>{if(simpleMapPointer&&Math.hypot(event.clientX-simpleMapPointer.x,event.clientY-simpleMapPointer.y)>8)simpleMapMoved=true},true);
document.addEventListener('pointerup',()=>{simpleMapPointer=null},true);
let draggedPayer='';document.addEventListener('dragstart',event=>{if(event.target.closest?.('button,a,input'))return;const row=event.target.closest?.('[data-payer-row]');if(row){draggedPayer=row.dataset.payerRow;row.classList.add('dragging-row')}},true);document.addEventListener('dragover',event=>{if(draggedPayer&&event.target.closest?.('[data-payer-row]'))event.preventDefault()},true);document.addEventListener('drop',event=>{const target=event.target.closest?.('[data-payer-row]');if(!target||!draggedPayer)return;event.preventDefault();const order=planPeople().map(person=>person.id),from=order.indexOf(draggedPayer),to=order.indexOf(target.dataset.payerRow);if(from>=0&&to>=0&&from!==to){order.splice(to,0,order.splice(from,1)[0]);trip().contributionPlan.participantOrder=order;commit('Ordem dos pagantes atualizada.')}draggedPayer=''},true);document.addEventListener('dragend',()=>{draggedPayer='';document.querySelectorAll('.dragging-row').forEach(row=>row.classList.remove('dragging-row'))},true);
document.addEventListener('input',event=>{if(!event.target.closest('#simple-plan'))return;const form=event.target.form,mode=form.elements.mode.value,count=Math.max(0,Number(form.elements.planPeopleCount.value)||0),payers=Math.min(count,Math.max(0,Number(form.elements.planPayerCount.value)||0)),months=Math.max(0,Number(form.elements.planCount.value)||0),monthly=cents(form.elements.planMonthly.value||0)||0,opening=cents(form.elements.planOpening.value||0)||0,goal=cents(form.elements.planGoal.value||0)||0,total=mode==='cost_split'?goal:opening+payers*months*monthly,needed=Math.max(0,goal-opening),suggested=payers&&months?Math.ceil(needed/(payers*months)):0,target=form.querySelector('[data-plan-preview]');if(target)target.innerHTML=`<span>${mode==='cost_split'?'Orçamento e mensalidade sugerida':'Previsão final da caixinha'}</span><strong>${cash(total)}</strong><small>${mode==='cost_split'?`${cash(suggested)} por pagante/mês após descontar o saldo inicial`:`${payers} pagantes × ${months} meses, mais ${cash(opening)} · ${count} viajantes`}</small>`},true);
document.addEventListener('input',event=>{if(!event.target.matches('#planPayerCount,#planPeopleCount'))return;const form=event.target.form,total=Math.max(1,Number(form.elements.planPeopleCount.value)||1),wanted=Math.min(total,Math.max(1,Number(form.elements.planPayerCount.value)||1));form.elements.planPayerCount.value=wanted;const boxes=[...form.querySelectorAll('[name="planParticipant"]')],checked=boxes.filter(box=>box.checked);if(checked.length>wanted)checked.slice(wanted).forEach(box=>box.checked=false);else if(checked.length<wanted)boxes.filter(box=>!box.checked).slice(0,wanted-checked.length).forEach(box=>box.checked=true)},true);

